const { createYoga, createSchema } = require('graphql-yoga');
const { createServer } = require('http');
const { GraphQLError } = require('graphql');
const mongoose = require('mongoose');

const PatientRecordSchema = new mongoose.Schema({
  ehrRecordId: String,
  patientMrn: String,
  assignedClinicId: String,
  diagnosisNotes: String,
  icd10Codes: [String],
  confidentialPrescriptions: [String]
});
const PatientRecord = mongoose.model('PatientRecord', PatientRecordSchema);

const yoga = createYoga({
  schema: createSchema({
    typeDefs: `
      type PatientHealthRecord @key(fields: "ehrRecordId") {
        ehrRecordId: ID!
        patientMrn: String!
        diagnosisNotes: String!
        icd10Codes: [String!]!
        confidentialPrescriptions: [String!]!
      }
      type Query { health: String }
    `,
    resolvers: {
      PatientHealthRecord: {
        __resolveReference: async ({ ehrRecordId }, context) => {
          if (!context.clinicId || !context.practitioner) {
            throw new GraphQLError('Practitioner authentication required', {
              extensions: { code: 'UNAUTHENTICATED' }
            });
          }

          // Enforce clinic tenancy and verify practitioner assignment
          const record = await PatientRecord.findOne({
            ehrRecordId,
            assignedClinicId: context.clinicId
          }).lean();

          if (!record) {
            throw new GraphQLError('Medical record not found or access restricted', {
              extensions: { code: 'FORBIDDEN' }
            });
          }

          return record;
        }
      }
    }
  }),
  context: ({ req }) => ({
    practitioner: req.headers['x-practitioner-id'],
    clinicId: req.headers['x-clinic-id']
  })
});

createServer(yoga).listen(4004);
